            num_parts.append('')
        num_parts[-1] += char

    products = []
    for part in num_parts:
        if part:
            products.append(int(part))

    for _ in range(K):
        max_product = 0
        max_pair = (0, 0)
        for i in range(len(products)):
            for j in range(i + 1, len(products)):
                product = products[i] * products[j]
                if product > max_product:
                    max_product = product
                    max_pair = (i, j)
