    if n <= 2:
        return 0

    max_length = [1] * n
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            max_length[i] = max_length[i - 1] + 1

    min_length = [1] * n
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            min_length[i] = min_length[i + 1] + 1

    max_choir_length = 2
